def choose_path(d, target_lag_s, streams, fetch_p99_s=2.0):
    paths = []
    # unknown fields are False until a probe proves them
    if d.webhook and d.delta:
        # bounded by the worst delivery latency; add a backstop poll if that is too slow
        lag = d.max_webhook_latency_s or 6 * 3600
        paths.append(('webhook+delta', lag, 1.0 * streams, None))
    if d.delta:
        for interval in (60, 300, 900, 3600):
            paths.append(('delta_poll', interval + fetch_p99_s, 3600 / interval * streams, interval))
    if d.list:
        for interval in (300, 900, 3600):
            paths.append(('list_poll', interval + fetch_p99_s, 3600 / interval * streams * 5, interval))
    ok = [p for p in paths if p[1] <= target_lag_s]
    budget = d.rate.limit * 3600 / d.rate.window_s
    ok = [p for p in ok if p[2] <= budget]            # must also fit the quota
    if not ok:
        return Choice(primary='live_only', backstop=None, sweep_every_s=604800, calls_per_hour=0)
    name, lag, calls, interval = min(ok, key=lambda p: p[2])   # cheapest that meets the lag
    backstop = interval or 900
    return Choice(primary=name, backstop=backstop, sweep_every_s=604800, calls_per_hour=calls)

