-- Redis hash per bucket, key: rl:{tenant}:{app}:{endpoint}
-- fields: tokens (float), ts_ms (int), paused_until_ms (int), rate (float/s), burst (float)
-- parent key: rl:{tenant}:{app} with the same fields
CREATE TABLE rate_quota (
  tenant_id text, app_id text, endpoint text,
  rate_per_s double precision NOT NULL, burst double precision NOT NULL,
  backfill_share double precision NOT NULL DEFAULT 0.5,
  PRIMARY KEY (tenant_id, app_id, endpoint)
);

