import hashlib, json, unicodedata
from urllib.parse import quote

def canon(o):
    # sorted keys, NFC text, trimmed whitespace, fixed number form
    if isinstance(o, str):
        return unicodedata.normalize('NFC', o).strip()
    if isinstance(o, float):
        return format(o, '.10g')
    if isinstance(o, dict):
        return {k: canon(o[k]) for k in sorted(o)}
    if isinstance(o, list):
        return [canon(x) for x in o]
    return o

def normalise(raw, kind, mapping, tenant, app):
    fields = {f: raw.get(f) for f in mapping.fields[kind] if f not in mapping.volatile}
    body = json.dumps(canon(fields), sort_keys=True, separators=(',', ':'), ensure_ascii=False)
    digest = hashlib.sha256(body.encode('utf-8')).hexdigest()
    native = quote(str(raw[mapping.id_field]), safe='')          # reserved characters escaped
    version = raw.get(mapping.revision_field) or raw['modified_at']
    return Envelope(uri=f'devx://{tenant}/{app}/{kind}/{native}', app=app, tenant=tenant,
                    kind=kind, version=str(version), content_hash=digest,
                    modified_at=raw['modified_at'], acl_ref=raw.get('acl_ref'),
                    title=raw.get('title'), container=raw.get('container'), author=raw.get('author'))

