import yaml, jsonschema, json, pathlib

SCHEMA = json.loads(pathlib.Path('vendors/schema.json').read_text())

def load_vendors(dir='vendors'):
    out = {}
    for p in pathlib.Path(dir).glob('*.yaml'):
        row = yaml.safe_load(p.read_text())
        jsonschema.validate(row, SCHEMA)       # a bad row fails the build
        out[row['app']] = row
    return out

def staleness_bound(c, poll_interval_s, fetch_p99_s):
    # plan from the WORST delivery latency, not the average
    push = c['max_delivery_latency_s'] if c['change_signal'] in ('webhook', 'webhook+delta') else float('inf')
    poll = poll_interval_s + fetch_p99_s
    return min(push, poll)

def must_be_live_only(c):
    return not c['store_allowed']
